<script setup lang="ts">import{ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';const includeSecrets=ref(false);const busy=ref(false);const message=ref('');async function create(){busy.value=true;message.value='';try{requireData(await client.POST('/api/admin/backups',{body:{includeSecrets:includeSecrets.value}}));message.value='备份已创建。'}catch(cause){message.value=errorMessage(cause)}finally{busy.value=false}}</script>
<template><PageHeader title="备份与恢复" description="备份包含一致的 SQLite 快照和数据文件。恢复仅在初始化阶段开放。"/><label class="flex gap-2"><input v-model="includeSecrets" type="checkbox">包含密钥（下载文件必须妥善保管）</label><button class="nw-button mt-4" :disabled="busy" @click="create">创建备份</button><p class="mt-3">{{ message }}</p></template>
